// 按照正则表达式进行切割
vector<string> splitByRegex(string str, string pattern) {
    regex re(pattern);
    sregex_token_iterator it(str.begin(), str.end(), re, -1);
    sregex_token_iterator end;
    vector<string> res;
    while (it != end) {
        // 忽略空字符串
        if (!it->str().empty()) {
            res.push_back(*it);
        }
        ++it;
    }
    return res;
}
