bool cmp(string s1, string s2) {
    set<char> set1(s1.begin(), s1.end());  // 计算 s1 唯一字符个数
    set<char> set2(s2.begin(), s2.end());  // 计算 s2 唯一字符个数
​
    if (set1.size() == set2.size()) {
        return s1 > s2;  // 按字典序降序排序
    }
    return set1.size() > set2.size();  // 唯一字符多的排前面
}
