import java.util.*;
import java.util.regex.*;
​
public class Main {
    // 按正则表达式进行切割
    public static List<String> splitByRegex(String str, String pattern) {
        List<String> res = new ArrayList<>();
        Pattern regex = Pattern.compile(pattern);
        Matcher matcher = regex.matcher(str);
        int lastEnd = 0;
​
        while (matcher.find()) {
            if (lastEnd < matcher.start()) {
                res.add(str.substring(lastEnd, matcher.start()));
            }
            lastEnd = matcher.end();
        }
        if (lastEnd < str.length()) {
            res.add(str.substring(lastEnd));
        }
        return res;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input1 = scanner.nextLine();
        String input2 = scanner.nextLine();
        scanner.close();
​
        // 分割取出有效字串
        List<String> splitString = splitByRegex(input1, "[0-9a-f]+");
​
        if (splitString.isEmpty()) {
            System.out.println("Not Found");
            return;
        }
​
        Set<Character> validChars = new HashSet<>();
        for (char c : input2.toCharArray()) {
            validChars.add(c);
        }
​
        List<String> valids = new ArrayList<>();
​
        // 取出所有满足条件的有效子串
        for (String str : splitString) {
            Set<Character> uniqueChars = new HashSet<>();
            for (char c : str.toCharArray()) {
                uniqueChars.add(c);
            }
​
            if (uniqueChars.size() > validChars.size()) {
                continue;
            }
            valids.add(str);
        }
​
        if (valids.isEmpty()) {
            System.out.println("Not Found");
            return;
        }
​
        // 自定义排序：唯一字符数优先，字典序降序
        valids.sort((a, b) -> {
            int uniqueA = new HashSet<>(Arrays.asList(a.chars().mapToObj(c -> (char) c).toArray(Character[]::new))).size();
            int uniqueB = new HashSet<>(Arrays.asList(b.chars().mapToObj(c -> (char) c).toArray(Character[]::new))).size();
​
            if (uniqueA != uniqueB) {
                return Integer.compare(uniqueB, uniqueA);
            }
            return b.compareTo(a);
        });
​
        System.out.println(valids.get(0));
    }
}
