    let validChars = new Set(input2);
    let valids = [];
​
    // 取出所有满足条件的有效子串
    splitString.forEach(str => {
        let uniqueChars = new Set(str);
        if (uniqueChars.size <= validChars.size) {
            valids.push(str);
