package main
​
import (
    "bufio"
    "fmt"
    "os"
    "regexp"
    "sort"
)
​
// 按照正则表达式切割字符串
func splitByRegex(str, pattern string) []string {
    re := regexp.MustCompile(pattern)
    split := re.Split(str, -1)
    var res []string
    for _, s := range split {
        if len(s) > 0 {
            res = append(res, s)
        }
    }
    return res
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取两行输入
    scanner.Scan()
    input1 := scanner.Text()
    scanner.Scan()
    input2 := scanner.Text()
​
    // 分割取出有效字串
    splitString := splitByRegex(input1, "[0-9a-f]+")
​
    if len(splitString) == 0 {
        fmt.Println("Not Found")
        return
    }
​
    validChars := make(map[rune]bool)
    for _, c := range input2 {
        validChars[c] = true
    }
​
    var valids []string
​
    // 取出所有满足条件的有效子串
    for _, str := range splitString {
        uniqueChars := make(map[rune]bool)
        for _, c := range str {
            uniqueChars[c] = true
        }
​
        if len(uniqueChars) > len(validChars) {
            continue
        }
        valids = append(valids, str)
    }
​
    if len(valids) == 0 {
        fmt.Println("Not Found")
        return
    }
​
    // 自定义排序
    sort.Slice(valids, func(i, j int) bool {
        uniqueI := len(mapify(valids[i]))
        uniqueJ := len(mapify(valids[j]))
​
        if uniqueI != uniqueJ {
            return uniqueI > uniqueJ
        }
        return valids[i] > valids[j] // 字典序降序
    })
​
    fmt.Println(valids[0])
}
​
// mapify 计算字符串的唯一字符数
func mapify(s string) map[rune]bool {
    m := make(map[rune]bool)
    for _, c := range s {
        m[c] = true
    }
    return m
}
